def get_divisors(n):
    divs = []
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divs.append(i)
            if i*i != n:
                divs.append(n // i)
    divs.sort()
    return divs

results = []
for n in range(1, 100000):
    divs = get_divisors(n)
    if len(divs) >= 5:
        a = divs[1]
        b = divs[2]
        c = divs[4]
        if a * b + b * c + c * a == n:
            results.append((n, len(divs)))

print(results)

